  t_agent_easy: 'Agent IA · simple', t_agent_mcp: 'Agent IA · MCP', a_title_easy: 'Agent IA — une seule instruction', a_title_mcp: 'Agent IA — serveur MCP',
  a_intro: 'Deux façons pour un agent IA d’utiliser cet outil à votre place. Les deux passent par le même filtre de commandes.', a_mode_prompt: 'Une instruction — rien à installer', a_mode_promptD: 'Collez une ligne dans Claude Code, ChatGPT ou Gemini. L’agent lit hoteltvapp.com, télécharge cet outil et l’exécute pour vous.', a_mode_mcp: 'Serveur MCP — avancé', a_mode_mcpD: 'Connectez cet outil directement à Claude. Des outils nommés, pas un shell brut.', a_rec: 'Recommandé', a_adv: 'Avancé',
  a_prompt_title: 'Copiez cette instruction', a_works: 'Claude Code · ChatGPT · Gemini', a_copy: 'Copier', a_copied: 'Copié', a_prompt_hint: 'Collez-la dans l’agent. Rien d’autre à installer à la main.', a_does: 'Ce que fait l’agent', a_d1: 'Lit hoteltvapp.com/boxsetupai', a_d2: 'Télécharge tv-setup et l’installe', a_d3: 'Exécute tv-setup --check --json, puis provisionne', a_d4: 'Ne vous demande que Autoriser / HOME sur la TV',
