  t_home: 'Launcher par défaut', l_title: 'Launcher par défaut', l_body: 'Faites de {app} l’écran d’accueil. Choisissez comment.', l_need: '{app} n’est pas encore installé. Installez-le d’abord — la TV ne peut choisir qu’une application qui existe.', l_goInst: 'Aller à Installer', l_cur: 'Application d’accueil actuelle', l_stock: 'Launcher d’origine',
